[tool error]
{
  "ok": false,
  "name": "draw_station_offset",
  "error": {
    "type": "invalid_params",
    "message": "['2791.37-20L'] is too short (at 'points')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "model (the default; stations are model feet)"
        },
        "alignment": {
          "type": "string",
          "minLength": 1,
          "description": "the alignment the stations are on (default the only one)"
        },
        "points": {
          "type": "array",
          "items": {
            "type": [
              "string",
              "number",
              "object"
            ],
            "description": "BEGIN | END | PI-n | PC-n | PT-n | MC-n | T-n | EQ-n | '86+50.00' | 8650, optionally '@offset' (ft, right +, e.g. 'PC-2@18', '86+50@25L'); or {ref|station, offset, region}. BC-n and EC-n, as a Caltrans plan letters them, are PC-n and PT-n"
          },
          "minItems": 2,
          "description": "station-and-offset points in order: '82+00@15R', '82+90@26R', 'PC-2@15L', 'END@18R', {station, offset}"
        },
        "follow": {
          "type": "boolean",
          "description": "between two points at the same offset, follow the alignment (arcs on its curves, exactly as draw_offset) instead of a straight chord (default true); where the offset changes the run is a straight taper"
        },
        "polyline": {
          "type": "boolean",
          "description": "draw one polyline (curves as arc segments) instead of lines and arcs"
        },
        "close": {
          "type": "boolean",
          "description": "close back to the first point"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        }
      },
      "required": [
        "points"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "ALIGN-1",
      "points": [
        "82+00@15R",
        "82+90@26R",
        "86+50@26R",
        "86+50@15R"
      ],
      "layer": "V-ROAD-EOP"
    }
  },
  "warnings": []
}

